// The evaluation report (generated by `lira eval`): what the system gets right and wrong against the answer key,
// what it does when the model misbehaves or is down, drift per firm, and how far the LLM judge agrees with people.

import { Fragment } from "react";
import { ApiError } from "../../shared/api/client";
import { useEvaluation } from "../../shared/api/hooks";
import { kindLabel } from "../../shared/ui/format";
import { EmptyState, ErrorState, Skeleton } from "../../shared/ui/states";
import "./evaluation.css";

const pct = (x: number | null | undefined) => (x == null ? "n/a" : `${(x * 100).toFixed(1)}%`);
const num = (x: string | number) => Number(x).toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

export function EvaluationPage() {
  const q = useEvaluation();
  if (q.isPending) return <main className="page"><Skeleton lines={14} label="Loading the evaluation" /></main>;
  if (q.isError) {
    return (
      <main className="page">
        {q.error instanceof ApiError && q.error.status === 404 ? (
          <EmptyState title="No evaluation yet">Run lira eval to produce the report this page shows.</EmptyState>
        ) : (
          <ErrorState title="The evaluation did not load" error={q.error} onRetry={() => q.refetch()} />
        )}
      </main>
    );
  }
  const r = q.data;
  const g = r.golden;
  return (
    <main className="page evaluation">
      <header className="page-head">
        <h1>Evaluation</h1>
        <p>
          {r.invoices_reviewed} invoices from {r.live_from}, scored against the simulation's answer key with the {r.model} model, on{" "}
          {r.generated_at}. Generated by the pipeline, not written by hand.
        </p>
      </header>

      <section className="eval-section">
        <h2>Money</h2>
        <dl className="figures">
          <Fig label="Taken by approved rules alone (three currencies)" value={num(g.auto_applied.money_taken)}
               note={`of which wrongly: ${num(g.auto_applied.money_taken_wrongly)}`} />
          <Fig label="Savings captured, reviewer accepts correct proposals" value={pct(g.money.accept_correct_proposals.captured_share)} />
          <Fig label="Savings captured, reviewer accepts everything" value={pct(g.money.accept_all_proposals.captured_share)}
               note={`taken wrongly: ${num(g.money.accept_all_proposals.taken_wrongly)}`} />
          <Fig label="Lines a language model read" value={pct(g.share_sent_to_model)}
               note={`${Number(g.reviewer_queue_lines_per_invoice).toFixed(1)} lines per invoice to decide`} />
        </dl>
      </section>

      <section className="eval-section">
        <h2>Judgement findings</h2>
        <table className="eval-table">
          <thead><tr><th scope="col">Finding</th><th scope="col">Precision</th><th scope="col">Recall</th><th scope="col">Under faults</th><th scope="col">Model down</th></tr></thead>
          <tbody>
            {Object.entries(g.judgement as Record<string, any>).map(([k, v]) => (
              <tr key={k}>
                <td>{kindLabel(k)}</td>
                <td>{pct(v.precision)}</td>
                <td>{pct(v.recall)}</td>
                <td>{pct(r.faults.judgement[k]?.recall)}</td>
                <td>{pct(r.outage.judgement[k]?.recall)}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <p className="eval-note">
          Under faults the model returns malformed output, invents clauses and quotes, and obeys instructions in entries:{" "}
          {r.faults.model_outputs.dropped_by_verifier} of {r.faults.model_outputs.decisions} model decisions were stopped by the verifier,{" "}
          {r.faults.ungrounded_model_findings_shown} ungrounded findings reached a reviewer, {r.faults.injection.decided_by_model} injected
          entries were decided by the model, and approved rules took {r.faults.auto_applied.money_taken_wrongly} wrongly.
        </p>
      </section>

      <section className="eval-section">
        <h2>Drift by firm</h2>
        <DriftGrid windows={r.drift.windows} />
        <p className="eval-note">Injected drift detected: {pct(r.drift.injected_drift_detected)}. Cells show the largest style PSI; a ring marks an alert.</p>
      </section>

      <section className="eval-section two">
        <div>
          <h2>Guidelines and retrieval</h2>
          <dl className="figures compact">
            <Fig label="Rules compiled" value={`${r.compile.totals.found} of ${r.compile.totals.expected}`} note={`${r.compile.totals.wrong_values} wrong values`} />
            <Fig label="Invented rules accepted" value={String(r.compile_faults.fabricated_rules_accepted)} note={`${r.compile_faults.rejected_by_verifier} refused`} />
            <Fig label="Retrieval recall at 5" value={pct(r.retrieval["recall@5"])} note={`cross-tenant hits: ${r.retrieval.cross_tenant_hits}`} />
            <Fig label="Unsupported answers shown" value={String(r.qa.unsupported_answers_shown)} note={`abstained on unanswerable: ${pct(r.qa.abstained_when_unanswerable)}`} />
          </dl>
        </div>
        <div>
          <h2>Appeals and the judge</h2>
          <dl className="figures compact">
            <Fig label="Appeal intent" value={pct(r.appeals.intent_accuracy)} />
            <Fig label="Recommendation right" value={pct(r.appeals.recommendation_accuracy)} note={`closed wrongly: ${r.appeals.closed_wrongly}`} />
            <Fig label="Judge verdicts changed by padding" value={`${r.judge.length_padding_flips} of ${r.judge.judged}`} />
            <Fig label="Judge agrees with answer key" value={pct(r.judge.judge_vs_answer_key.correct_criterion_matches_answer_key)} />
          </dl>
          {r.judge.agreement && <AgreementTable a={r.judge.agreement} />}
        </div>
      </section>
    </main>
  );
}

function Fig({ label, value, note }: { label: string; value: string; note?: string }) {
  return (
    <div className="fig">
      <dt>{label}</dt>
      <dd>
        <span className="fig-value">{value}</span>
        {note && <span className="fig-note">{note}</span>}
      </dd>
    </div>
  );
}

function DriftGrid({ windows }: { windows: { firm: string; month: string; lines: number; max_psi: number; alert: boolean; drivers: string[] }[] }) {
  const firms = [...new Set(windows.map((w) => w.firm))];
  const months = [...new Set(windows.map((w) => w.month))].sort();
  const cell = (f: string, m: string) => windows.find((w) => w.firm === f && w.month === m);
  return (
    <div className="drift" style={{ gridTemplateColumns: `8rem repeat(${months.length}, minmax(4.5rem, 1fr))` }} role="table" aria-label="Drift by firm and month">
      <span role="columnheader" />
      {months.map((m) => <span key={m} role="columnheader" className="drift-month">{m}</span>)}
      {firms.map((f) => (
        <Fragment key={f}>
          <span role="rowheader" className="drift-firm">{f}</span>
          {months.map((m) => {
            const w = cell(f, m);
            const level = w ? Math.min(1, w.max_psi / 0.5) : 0;
            return (
              <span key={m} role="cell" className={`drift-cell${w?.alert ? " is-alert" : ""}`} style={{ ["--level" as string]: level }}
                    title={w ? `${w.lines} lines, PSI ${w.max_psi.toFixed(2)}${w.drivers.length ? `, ${w.drivers.join(", ")}` : ""}` : "no data"}>
                {w ? w.max_psi.toFixed(2) : ""}
              </span>
            );
          })}
        </Fragment>
      ))}
    </div>
  );
}

function AgreementTable({ a }: { a: Record<string, any> }) {
  const rows = ["supported", "correct", "specific", "professional", "overall"];
  return (
    <table className="eval-table">
      <thead><tr><th scope="col">Criterion</th><th scope="col">Annotators (kappa)</th><th scope="col">Judge vs adjudicated (kappa)</th></tr></thead>
      <tbody>
        {rows.map((c) => (
          <tr key={c}><td>{c}</td><td>{a[c]?.annotators_kappa ?? "n/a"}</td><td>{a[c]?.judge_vs_gold_kappa ?? "n/a"}</td></tr>
        ))}
      </tbody>
    </table>
  );
}
